saveQuestion=async()=>{const body=document.querySelector('#newBody').value.trim(),answers=[0,1,2,3].map(i=>document.querySelector('#newAnswer'+i).value.trim());if(!body||answers.some(a=>!a))return alert('Renseignez la question et les quatre propositions.');const theme=document.querySelector('#newThemeName').value.trim()||document.querySelector('#newTheme').value,newChapter=document.querySelector('#newChapterName').value.trim();let chapter=data.chapters.find(c=>c.id===document.querySelector('#newChapter').value);if(newChapter){chapter={id:'local-'+Date.now(),theme,title:newChapter,quiz:{title:`Quiz — ${newChapter}`,questions:[]}};data.chapters.push(chapter)}const question={id:'q'+Date.now(),body,seconds:Number(document.querySelector('#newSeconds').value)||30,answers,correct:Number(document.querySelector('#newCorrect').value),explanation:document.querySelector('#newExplanation').value||'Réponse enregistrée.',position:chapter.quiz.questions.length};try{if(chapter.id.startsWith('local-'))throw new Error('Le nouveau thème ou chapitre est disponible dans l’interface, mais doit d’abord être créé dans Supabase avant d’y enregistrer une question.');await createQuestion(data.chapters.indexOf(chapter),question);chapter.quiz.questions.push(question);save();closeModal();admin();setTimeout(()=>adminPanel('content'),0);alert('Question et quatre propositions enregistrées dans Supabase.')}catch(error){if(chapter.id.startsWith('local-')){chapter.quiz.questions.push(question);save();closeModal();admin();setTimeout(()=>adminPanel('content'),0);alert(error.message)}else alert(`La question n’a pas été enregistrée dans Supabase : ${error.message}`)}};
