const enhancedAdmin=()=>{if(!getSession())return showAdminLogin();layout(`<div class="layout"><aside class="sidebar"><p>Administration</p><button class="nav-button active" onclick="adminPanel('create',this)">Créer une session</button><button class="nav-button" onclick="adminPanel('content',this)">Questions</button><button class="nav-button" onclick="adminPanel('scheduled',this)">Quiz programmés</button><button class="nav-button" onclick="adminPanel('performance',this)">Performances</button><button class="nav-button" onclick="adminPanel('settings',this)">Réglages</button><button class="nav-button" onclick="logoutAdmin()">Déconnexion</button></aside><section><div id="create" class="panel active"><h1>Créer un quiz programmé</h1><div class="card"><label>Chapitre / quiz</label><select id="sessionChapter">${data.chapters.map(c=>`<option value="${c.id}">${esc(c.theme||data.theme)} · ${esc(c.title)}</option>`).join('')}</select><label>Nom de la session</label><input id="sessionTitle"><p><button class="button" onclick="createSession()">Créer et générer le QR code</button></p></div><div id="createdSession"></div></div><div id="content" class="panel"><div class="row"><h1>Questions</h1><button class="button" onclick="openQuestionModal()">+ Ajouter une question</button></div><div class="card" style="margin-top:18px"><div class="tabs">${data.chapters.map(c=>`<button class="tab" onclick="renderQuestions('${c.id}',this)">${esc(c.title)}</button>`).join('')}</div><table><thead><tr><th>Question</th><th>Temps</th><th>Réponses</th></tr></thead><tbody id="questionRows"></tbody></table></div></div><div id="scheduled" class="panel"><div class="row"><h1>Quiz programmés</h1><button class="button secondary" onclick="exportSessions()">Exporter Excel</button></div><div class="card"><table><thead><tr><th>Quiz / code</th><th>Thème</th><th>Chapitre</th><th>État</th><th>Actions</th></tr></thead><tbody>${sessions.map(s=>{const c=data.chapters.find(x=>x.id===s.chapterId);return `<tr><td>${esc(s.title)}<br><small>${s.code}</small></td><td>${esc(c?.theme||data.theme)}</td><td>${esc(c?.title||'')}</td><td>${esc(s.status)}</td><td><button class="button secondary" onclick="editSession('${s.code}')">Modifier</button> <button class="button secondary" onclick="duplicateSession('${s.code}')">Dupliquer</button> <button class="button danger" onclick="deleteQuizSession('${s.code}')">Supprimer</button></td></tr>`}).join('')||'<tr><td colspan="5">Aucun quiz programmé.</td></tr>'}</tbody></table></div></div><div id="performance" class="panel"><h1>Performances individuelles</h1><select id="performanceSession" onchange="renderPerformance()"><option value="">Sélectionner une session</option>${sessions.map(s=>`<option value="${s.code}">${esc(s.title)}</option>`).join('')}</select><div id="performanceRows" class="card" style="margin-top:18px">Sélectionnez une session.</div></div><div id="settings" class="panel"><h1>Réglages</h1><div class="card"><label>Seuil de réussite</label><input value="70 %"><label>Capacité maximum</label><input type="number" value="30"></div></div></section></div>`);renderQuestions(data.chapters[0].id)};
const enhancedQuestionModal=()=>{app.insertAdjacentHTML('beforeend',`<div class="modal" id="modal"><div class="card"><div class="row"><h2>Ajouter une question</h2><button class="button secondary" onclick="closeModal()">Fermer</button></div><div class="form-grid"><div><label>Thème existant</label><select id="newTheme" onchange="updateQuestionChapters()">${enhancedThemes().map(t=>`<option value="${esc(t)}">${esc(t)}</option>`).join('')}</select></div><div><label>Nouveau thème (facultatif)</label><input id="newThemeName"></div><div><label>Chapitre existant</label><select id="newChapter"></select></div><div><label>Nouveau chapitre (facultatif)</label><input id="newChapterName"></div></div><label>Question</label><textarea id="newBody"></textarea><div class="form-grid"><div><label>Temps</label><input id="newSeconds" type="number" value="30"></div><div><label>Bonne réponse</label><select id="newCorrect"><option value="0">A</option><option value="1">B</option><option value="2">C</option><option value="3">D</option></select></div></div>${['A','B','C','D'].map((l,i)=>`<label>Proposition ${l}<input id="newAnswer${i}"></label>`).join('')}<label>Explication</label><textarea id="newExplanation"></textarea><p><button class="button" onclick="saveQuestion()">Enregistrer</button></p></div></div>`);enhancedUpdateChapters()};
const enhancedUpdateChapters=()=>{const select=document.querySelector('#newChapter'),theme=document.querySelector('#newTheme')?.value;if(select)select.innerHTML=enhancedChapters(theme).map(c=>`<option value="${c.id}">${esc(c.title)}</option>`).join('')};
const enhancedSaveQuestion=async()=>{const body=document.querySelector('#newBody').value.trim(),answers=[0,1,2,3].map(i=>document.querySelector('#newAnswer'+i).value.trim());if(!body||answers.some(x=>!x))return alert('Renseignez la question et les quatre propositions.');let chapter=data.chapters.find(c=>c.id===document.querySelector('#newChapter').value),newName=document.querySelector('#newChapterName').value.trim(),theme=document.querySelector('#newThemeName').value.trim()||document.querySelector('#newTheme').value;if(newName){chapter={id:'local-'+Date.now(),theme,title:newName,quiz:{title:`Quiz — ${newName}`,questions:[]}};data.chapters.push(chapter)}const question={id:'q'+Date.now(),body,seconds:Number(document.querySelector('#newSeconds').value)||30,answers,correct:Number(document.querySelector('#newCorrect').value),explanation:document.querySelector('#newExplanation').value||'',position:chapter.quiz.questions.length};if(chapter.id.startsWith('local-')){chapter.quiz.questions.push(question);save();closeModal();enhancedAdmin();return alert('Nouveau thème/chapitre ajouté localement. Créez sa structure dans Supabase avant la synchronisation.')}try{await createQuestion(data.chapters.indexOf(chapter),question);chapter.quiz.questions.push(question);save();closeModal();enhancedAdmin();alert('Question enregistrée dans Supabase.')}catch(e){alert(`Enregistrement Supabase impossible : ${e.message}`)}};
const enhancedLearner=()=>{clearInterval(timer);const s=sessionByCode(activeSession?.code),q=s&&quizFor(s)?.questions[s.questionIndex];if(!s||s.status!=='live')return waiting();if(!q)return learnerEnd();answerChoice=s.answers?.[learnerName]??null;const locked=s.paused||Math.ceil((s.endsAt-Date.now())/1000)<=0;layout(`<div class="question-head"><h1>Question ${s.questionIndex+1}</h1><div class="timer" id="countdown"></div></div><div class="card"><p class="question">${esc(q.body)}</p><div class="answers">${q.answers.map((a,i)=>`<label class="answer ${locked?'locked':''}"><input type="radio" name="answer" ${locked?'disabled':''} onchange="answerChoice=${i}"><span class="answer-letter">${'ABCD'[i]}</span>${esc(a)}</label>`).join('')}</div><div id="learnerFeedback"></div><p><button id="validateAnswer" class="button" ${locked||answerChoice!==null?'disabled':''} onclick="submitAnswer()">Valider ma réponse</button></p></div>`);const lock=(msg,all)=>{const b=document.querySelector('#validateAnswer');if(b){b.disabled=true;b.textContent=all?'Question verrouillée':'Réponse validée'}if(all)document.querySelectorAll('input[name="answer"]').forEach(x=>{x.disabled=true;x.closest('.answer')?.classList.add('locked')});document.querySelector('#learnerFeedback').innerHTML=`<div class="feedback">${msg}</div>`};const tick=()=>{const current=sessionByCode(activeSession?.code),left=Math.max(0,Math.ceil(((current?.endsAt||0)-Date.now())/1000)),el=document.querySelector('#countdown');if(el)el.textContent=left+'s';if(current?.paused||left<=0){clearInterval(timer);lock(current?.paused?'Quiz mis en pause par l’instructeur.':'Le temps est écoulé.',true)}};tick();if(!locked)timer=setInterval(tick,400)};
const enhancedSubmit=()=>{if(answerChoice===null)return alert('Choisissez une proposition.');const s=sessionByCode(activeSession.code);if(s.paused||Math.ceil((s.endsAt-Date.now())/1000)<=0)return enhancedLearner();s.answers??={};s.answerHistory??={};s.answerHistory[learnerName]??={};s.answers[learnerName]=answerChoice;s.answerHistory[learnerName][s.questionIndex]=answerChoice;save();const button=document.querySelector('#validateAnswer');button.disabled=true;button.textContent='Réponse validée';document.querySelector('#learnerFeedback').innerHTML='<div class="feedback">Réponse enregistrée. Attendez la consigne.</div>'};
const enhancedStart=()=>{const s=sessionByCode(activeSession.code),q=quizFor(s).questions[s.questionIndex],restart=!s.paused||s.status==='polling'||s.remainingSeconds===0;if(restart){s.answers={};s.remainingSeconds=q.seconds}else s.remainingSeconds=s.remainingSeconds??q.seconds;s.status='live';s.paused=false;s.endsAt=Date.now()+s.remainingSeconds*1000;save();enhancedPilot()};
const enhancedPause=()=>{const s=sessionByCode(activeSession.code);s.remainingSeconds=Math.max(0,Math.ceil((s.endsAt-Date.now())/1000));s.paused=true;save();enhancedPilot()};
const enhancedNext=()=>{const s=sessionByCode(activeSession.code),quiz=quizFor(s);s.questionIndex++;s.answers={};s.paused=false;s.remainingSeconds=null;s.status=s.questionIndex>=quiz.questions.length?'finished':'waiting';save();enhancedPilot()};
const enhancedPerformance=()=>{const s=sessionByCode(document.querySelector('#performanceSession').value),box=document.querySelector('#performanceRows');if(!s)return;const q=quizFor(s),people=[...new Set([...s.participants,...Object.keys(s.answerHistory||{})])];box.innerHTML=`<table><thead><tr><th>Apprenant</th><th>Réponses</th><th>Bonnes réponses</th><th>Score</th></tr></thead><tbody>${people.map(name=>{const h=s.answerHistory?.[name]||{},answered=Object.keys(h).length,correct=Object.entries(h).filter(([i,a])=>q.questions[i]?.correct===a).length;return `<tr><td>${esc(name)}</td><td>${answered}</td><td>${correct}</td><td>${answered?Math.round(correct*100/answered):0}%</td></tr>`}).join('')}</tbody></table>`};
const enhancedExport=()=>{const rows=[['Quiz','Code','Thème','Chapitre','État'],...sessions.map(s=>{const c=data.chapters.find(x=>x.id===s.chapterId);return [s.title,s.code,c?.theme||data.theme,c?.title||'',s.status]})],html=`<table>${rows.map(r=>`<tr>${r.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</table>`,blob=new Blob(['\ufeff'+html],{type:'application/vnd.ms-excel'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='quiz-programmes.xls';a.click();URL.revokeObjectURL(a.href)};
const enhancedEdit=key=>{const s=sessionByCode(key),title=prompt('Nom de la session',s.title);if(title?.trim()){s.title=title.trim();save();enhancedAdmin()}};
const enhancedDuplicate=key=>{const s=sessionByCode(key);sessions.unshift(enhancedSession(s.chapterId,`${s.title} — copie`));save();enhancedAdmin()};
const enhancedCreate=()=>{const chapterId=document.querySelector('#sessionChapter').value,c=data.chapters.find(x=>x.id===chapterId),s=enhancedSession(chapterId,document.querySelector('#sessionTitle').value.trim()||c.quiz.title);sessions.unshift(s);save();document.querySelector('#createdSession').innerHTML=`<div class="card center"><h2>${esc(s.title)}</h2><img class="generated-qr" src="${qr(s.code)}" alt="QR code"><div class="code">${s.code}</div><input readonly value="${esc(sessionUrl(s.code))}"></div>`};
instructor=enhancedInstructor;admin=enhancedAdmin;renderPilot=enhancedPilot;showPoll=enhancedPoll;startLive=enhancedStart;pauseLive=enhancedPause;nextLiveQuestion=enhancedNext;selectSession=key=>{activeSession=sessionByCode(key);instructorPanel('pilot');enhancedPilot()};createSession=enhancedCreate;openQuestionModal=enhancedQuestionModal;updateQuestionChapters=enhancedUpdateChapters;saveQuestion=enhancedSaveQuestion;learnerQuiz=enhancedLearner;submitAnswer=enhancedSubmit;editSession=enhancedEdit;duplicateSession=enhancedDuplicate;renderPerformance=enhancedPerformance;exportSessions=enhancedExport;loginAdmin=async()=>{const email=document.querySelector('#adminEmail').value.trim(),password=document.querySelector('#adminPassword').value;try{await signIn(email,password);closeAdminLogin();enhancedAdmin()}catch(e){alert(e.message)}};
Object.assign(window,{admin,instructor,renderPilot,showPoll,startLive,pauseLive,nextLiveQuestion,selectSession,createSession,openQuestionModal,updateQuestionChapters,saveQuestion,learnerQuiz,submitAnswer,editSession,duplicateSession,renderPerformance,exportSessions});
window.finishLive=enhancedFinish;
